using System;
using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;

namespace Media.DBContext.Models;

/// <summary>
/// Represents a link, which allows anonymous download of the contained records.
/// </summary>
[Table("share_links")]
public class ShareLink
{
  /// <summary>
  /// Primary key. Autogenerated.
  /// </summary>
  [Key]
  public Guid ShareLinkId { get; set; }

  /// <summary>
  /// SHA-256 hash of the secret token, as hex string.
  /// </summary>
  [Required]
  public string TokenHash { get; set; } = null!;

  /// <summary>
  /// Date when the link was created.
  /// </summary>
  public DateTime CreatedAt { get; set; }

  /// <summary>
  /// Date when the link expires.
  /// </summary>
  public DateTime ExpiresAt { get; set; }

  /// <summary>
  /// True, if the link can be used only once.
  /// </summary>
  public bool SingleUse { get; set; }

  /// <summary>
  /// Date when the link was used, if it is a single use link.
  /// </summary>
  public DateTime? UsedAt { get; set; }

  /// <summary>
  /// Subject of the admin or client, who created the link.
  /// </summary>
  public string CreatedBy { get; set; } = string.Empty;

  /// <summary>
  /// True, if an admin created the link.
  /// </summary>
  public bool CreatedByAdmin { get; set; }

  /// <summary>
  /// Ids of the records to be downloaded.
  /// </summary>
  public List<Guid> RecordIds { get; set; } = [];
}
